-- Better Auth identity tables (ADR-0003). PostgreSQL 18. Forward-only: never edit after it is applied.
-- Global identity tables, not clinic-owned: no clinic_id and no RLS. Isolation is by grants instead —
-- only eyadex_auth may touch them; eyadex_app, eyadex_platform and eyadex_dispatcher get nothing.
-- ids are UUID v7 generated by the application (Better Auth's generateId hook); no database defaults
-- anywhere — Better Auth supplies every default value itself.
-- Column optionality follows Better Auth 1.7 exactly (required → NOT NULL).

CREATE TABLE auth_users (
  id                 uuid PRIMARY KEY,
  name               text NOT NULL,
  email              text NOT NULL UNIQUE,
  email_verified     boolean NOT NULL,
  image              text NULL,
  two_factor_enabled boolean NULL,
  created_at         timestamptz NOT NULL,
  updated_at         timestamptz NOT NULL
);

CREATE TABLE auth_sessions (
  id         uuid PRIMARY KEY,
  user_id    uuid NOT NULL REFERENCES auth_users (id) ON DELETE CASCADE,
  token      text NOT NULL UNIQUE,
  expires_at timestamptz NOT NULL,
  ip_address text NULL,
  user_agent text NULL,
  -- The area that issued the session (PRD §4.15). Both areas share this table and the signing
  -- secret, so the cookie name alone cannot keep a clinic session off the platform host: the
  -- session check compares this column with the area of the instance reading it.
  area       text NOT NULL CHECK (area IN ('platform', 'clinic')),
  created_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL
);
CREATE INDEX auth_sessions_user_id_idx ON auth_sessions (user_id);

-- One row per sign-in method; the credential row holds Better Auth's password hash.
CREATE TABLE auth_accounts (
  id                       uuid PRIMARY KEY,
  user_id                  uuid NOT NULL REFERENCES auth_users (id) ON DELETE CASCADE,
  account_id               text NOT NULL,
  provider_id              text NOT NULL,
  access_token             text NULL,
  refresh_token            text NULL,
  id_token                 text NULL,
  access_token_expires_at  timestamptz NULL,
  refresh_token_expires_at timestamptz NULL,
  scope                    text NULL,
  password                 text NULL,
  created_at               timestamptz NOT NULL,
  updated_at               timestamptz NOT NULL,
  UNIQUE (provider_id, account_id)
);
CREATE INDEX auth_accounts_user_id_idx ON auth_accounts (user_id);

CREATE TABLE auth_verifications (
  id         uuid PRIMARY KEY,
  identifier text NOT NULL,
  value      text NOT NULL,
  expires_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL
);
CREATE INDEX auth_verifications_identifier_idx ON auth_verifications (identifier);

-- TOTP secret (encrypted by Better Auth with BETTER_AUTH_SECRET) and backup codes.
CREATE TABLE auth_two_factors (
  id                        uuid PRIMARY KEY,
  user_id                   uuid NOT NULL REFERENCES auth_users (id),
  secret                    text NOT NULL,
  backup_codes              text NOT NULL,
  -- NOT NULL: Better Auth reads `verified !== false` as verified and adds 1 to the failure count
  -- for its lockout; NULL would read as verified and never reach the limit. Better Auth always
  -- writes both (false / 0) on create.
  verified                  boolean NOT NULL,
  failed_verification_count integer NOT NULL,
  locked_until              timestamptz NULL,
  -- One row per user: Better Auth 1.7.7 enrolls with an unguarded findOne + create, so two
  -- overlapping first enrollments would otherwise leave two secrets and later lookups pick one
  -- without ordering. The loser of the race gets a unique violation; the winner's QR is the row.
  UNIQUE (user_id)
);

-- 0013 revoked PUBLIC on every table that existed then; these are new, so revoke again explicitly.
REVOKE ALL ON auth_users, auth_sessions, auth_accounts, auth_verifications, auth_two_factors
  FROM PUBLIC, eyadex_app, eyadex_platform, eyadex_dispatcher;

-- Users are never deleted (CLAUDE.md §5): no DELETE on auth_users. Sessions, verifications,
-- two-factor rows and accounts are deleted by Better Auth (sign-out, revocation, expiry, disabling 2FA).
GRANT SELECT, INSERT, UPDATE ON auth_users TO eyadex_auth;
GRANT SELECT, INSERT, UPDATE, DELETE ON auth_sessions, auth_accounts, auth_verifications,
  auth_two_factors TO eyadex_auth;
